function findPattern(board, pattern) {
  const rows = board.length;
  const cols = board[0].length;
  const height = pattern.length;
  const width = pattern[0].length;

  const matches = (top, left) => {
    const letterToDigit = new Map();
    const digitToLetter = new Map();
    for (let i = 0; i < height; i++) {
      for (let j = 0; j < width; j++) {
        const symbol = pattern[i][j];
        const digit = board[top + i][left + j];
        if (symbol >= '0' && symbol <= '9') {
          if (Number(symbol) !== digit) return false;
          continue;
        }
        if (letterToDigit.has(symbol) && letterToDigit.get(symbol) !== digit) return false;
        if (digitToLetter.has(digit) && digitToLetter.get(digit) !== symbol) return false;
        letterToDigit.set(symbol, digit);
        digitToLetter.set(digit, symbol);
      }
    }
    return true;
  };

  for (let top = 0; top + height <= rows; top++) {
    for (let left = 0; left + width <= cols; left++) {
      if (matches(top, left)) return [top, left];
    }
  }
  return [-1, -1];
}

