function findPattern(board, pattern) {
  const isLetter = ch => ch >= 'a' && ch <= 'z';
  for (let r = 0; r + pattern.length <= board.length; r++) {
    for (let c = 0; c + pattern[0].length <= board[0].length; c++) {
      // Read each letter's digit from its first cell, then rebuild the pattern and compare.
      const assigned = new Map();
      pattern.forEach((line, i) => [...line].forEach((ch, j) => { if (isLetter(ch) && !assigned.has(ch)) assigned.set(ch, board[r + i][c + j]); }));
      if (new Set(assigned.values()).size !== assigned.size) continue;
      const rebuilt = pattern.map(line => [...line].map(ch => isLetter(ch) ? String(assigned.get(ch)) : ch).join(''));
      const window = pattern.map((_, i) => board[r + i].slice(c, c + pattern[0].length).join(''));
      if (rebuilt.join('|') === window.join('|')) return [r, c];
    }
  }
  return [-1, -1];
}

