function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const rows = large ? int(40, 50) : int(1, 5);
  const cols = large ? int(40, 50) : int(1, 5);
  const top = large ? [1, 3, 9][int(0, 2)] : [1, 2, 9][int(0, 2)];
  const board = Array.from({ length: rows }, () => Array.from({ length: cols }, () => int(0, top)));
  const height = large ? int(1, Math.min(rows, [3, 6, 25][int(0, 2)])) : int(1, 3);
  const width = large ? int(1, Math.min(cols, [3, 6, 25][int(0, 2)])) : int(1, 3);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let pattern;
  if (height <= rows && width <= cols && rand() < 0.7) {
    // Plant a window: each digit gets its own letter, and some cells keep the digit itself.
    const r0 = int(0, rows - height), c0 = int(0, cols - width);
    const shift = int(0, 16);
    const keep = rand() * 0.6;
    pattern = Array.from({ length: height }, (_, i) => Array.from({ length: width }, (_, j) => {
      const d = board[r0 + i][c0 + j];
      return rand() < keep ? String(d) : letters[d + shift];
    }).join(''));
    if (rand() < 0.3) {
      const i = int(0, height - 1), j = int(0, width - 1);
      const ch = rand() < 0.5 ? letters[int(0, 25)] : String(int(0, 9));
      pattern[i] = pattern[i].slice(0, j) + ch + pattern[i].slice(j + 1);
    }
  } else {
    const symbols = rand() < 0.5 ? 'ab0' : 'abc12';
    pattern = Array.from({ length: height }, () => Array.from({ length: width }, () => symbols[int(0, symbols.length - 1)]).join(''));
  }
  return [board, pattern];
}
